#!/usr/bin/env python3
"""Evaluate the preprocess_mc detector at scale 3 against every PDF in Year/MC."""
from __future__ import annotations

import csv
import gc
import io
import json
import re
import subprocess
import sys
from pathlib import Path

import fitz
from PIL import Image


def _image_bytes(image: Image.Image) -> bytes:
    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()


def page_text(page: fitz.Page, scale: float = 1.5) -> str:
    pixmap = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
    image = Image.frombytes("RGB", (pixmap.width, pixmap.height), pixmap.samples)
    result = subprocess.run(
        ["tesseract", "stdin", "stdout", "--psm", "6"],
        input=_image_bytes(image),
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=True,
    )
    text = result.stdout.decode("utf-8", errors="ignore").lower()
    del result, image, pixmap
    gc.collect()
    return text


def is_formula_sheet(page: fitz.Page) -> bool:
    text = page_text(page)
    return "formula sheet" in text or "data sheet" in text or "physical constants" in text


def detect_labels(page: fitz.Page, scale: float, questions: int) -> list[tuple[int, float, float]]:
    pixmap = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
    image = Image.frombytes("RGB", (pixmap.width, pixmap.height), pixmap.samples)
    found: list[tuple[int, float, float]] = []
    for config in ("--psm 11", "--psm 6"):
        result = subprocess.run(
            ["tesseract", "stdin", "stdout", "--psm", config.split()[-1], "tsv"],
            input=io.BytesIO(_image_bytes(image)).getvalue(),
            stdout=subprocess.PIPE,
            check=True,
        )
        rows = csv.DictReader(result.stdout.decode("utf-8").splitlines(), delimiter="\t")
        for row in rows:
            text = row["text"].strip()
            x, y = float(row["left"]) / scale, float(row["top"]) / scale
            if not text or not 35 <= x <= 90 or not 35 <= y <= 735:
                continue
            match = re.fullmatch(r"\*?(\d{1,2})[.,]?", text)
            if not match:
                continue
            number = int(match.group(1))
            if not 1 <= number <= questions:
                continue
            candidate = (number, x, y)
            if not any(number == old[0] and abs(x - old[1]) < 8 and abs(y - old[2]) < 12 for old in found):
                found.append(candidate)
    del result, image, pixmap
    gc.collect()
    return found


def evaluate(pdf: Path, questions: int = 36) -> dict:
    doc = fitz.open(pdf)
    cover_pages = 1
    excluded = {i for i in range(cover_pages, len(doc)) if is_formula_sheet(doc[i])}
    content = [i for i in range(cover_pages, len(doc)) if i not in excluded]

    by_page: dict[int, list[tuple[int, float, float]]] = {p: [] for p in content}
    # Run detector at scale 3 only (user request).
    for p in content:
        for number, x, y in detect_labels(doc[p], 3, questions):
            by_page[p].append((number, x, y))

    # Group numbers per page.
    page_of_number: dict[int, int] = {}
    page_detections: dict[int, dict[int, list[tuple[float, float]]]] = {}
    for p in content:
        page_detections[p] = {}
        for number, x, y in by_page[p]:
            page_detections[p].setdefault(number, []).append((x, y))
    # First detection wins (matches setdefault behaviour in the original script).
    for p in content:
        for number, locs in page_detections[p].items():
            if number not in page_of_number:
                page_of_number[number] = p
    detected = sorted(page_of_number)
    missing = sorted(set(range(1, questions + 1)) - set(detected))

    # Look for duplicate detections within the same number on different pages or far apart on same page.
    duplicates = {}
    for p in content:
        for number, locs in page_detections[p].items():
            if len(locs) > 1:
                # Are they close together (within dedup radius)?
                far = []
                for i in range(len(locs)):
                    for j in range(i + 1, len(locs)):
                        if abs(locs[i][0] - locs[j][0]) >= 8 or abs(locs[i][1] - locs[j][1]) >= 12:
                            far.append((locs[i], locs[j]))
                duplicates.setdefault(number, []).append({"page": p, "locs": locs, "far_pairs": far})

    # Pages that contain any label.
    pages_with_labels = sorted({p for p, d in page_detections.items() if d})

    return {
        "pdf": pdf.name,
        "total_pages": len(doc),
        "cover_pages": cover_pages,
        "excluded_pages": sorted(excluded),
        "content_pages": content,
        "pages_with_labels": pages_with_labels,
        "detected_numbers": detected,
        "missing_numbers": missing,
        "number_to_page": {n: p + 1 for n, p in page_of_number.items()},  # 1-indexed
        "page_detections": {p + 1: {n: locs for n, locs in sorted(d.items())} for p, d in page_detections.items()},
        "duplicates": duplicates,
    }


def main() -> None:
    base = Path("/Users/sinchunyeung/Documents-local/Materials/Phy/DSE")
    mc_dir = base / "Year" / "MC"
    out_path = Path("/tmp/mc_detector_eval.json")
    results = {}
    for pdf in sorted(mc_dir.glob("*.pdf")):
        print(f"Evaluating {pdf.name}...", file=sys.stderr)
        results[pdf.name] = evaluate(pdf)
    out_path.write_text(json.dumps(results, indent=2, default=str))
    print(f"Wrote {out_path}", file=sys.stderr)


if __name__ == "__main__":
    main()
